arguments.file_text:
@page "/chat"
@rendermode InteractiveServer
@inject IChatService ChatService
@implements IDisposable

<PageTitle>Team Chat</PageTitle>

<div class="chat-container">
    @* Left Sidebar - Channel List *@
    <aside class="channel-sidebar">
        <div class="sidebar-header">
            <h3>Channels</h3>
        </div>
        <ul class="channel-list">
            @foreach (var channel in _channels)
            {
                <li class="channel-item @(channel.Id == _activeChannelId ? "active" : "")"
                    @onclick="() => SelectChannelAsync(channel)">
                    <div class="channel-name"># @channel.Name</div>
                    <div class="channel-description">@TruncateDescription(channel.Description)</div>
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="unread-badge">@channel.UnreadCount</span>
                    }
                </li>
            }
        </ul>
    </aside>

    @* Main Message Area *@
    <main class="message-area @(_threadOpen ? "thread-open" : "")">
        @if (_activeChannel is not null)
        {
            <div class="message-header">
                <h2># @_activeChannel.Name</h2>
                <p>@_activeChannel.Description</p>
            </div>

            <div class="message-list" @onscroll="OnMessageListScroll" @ref="_messageListRef">
                @if (_loadingMore)
                {
                    <div class="loading-indicator">Loading older messages...</div>
                }
                @foreach (var message in _messages)
                {
                    <div class="message-item" @onmouseenter="() => _hoveredMessageId = message.Id"
                         @onmouseleave="() => _hoveredMessageId = null">
                        <div class="message-content-wrapper">
                            <div class="message-author">@message.Author</div>
                            <div class="message-timestamp">@FormatRelativeTime(message.SentAt)</div>
                            <div class="message-text">@message.Content</div>

                            @if (message.Reactions.Count > 0)
                            {
                                <div class="reaction-row">
                                    @foreach (var reaction in message.Reactions)
                                    {
                                        <span class="reaction-badge" @onclick="() => AddReactionAsync(message.Id, reaction.Emoji)">
                                            @reaction.Emoji @reaction.Users.Count
                                        </span>
                                    }
                                </div>
                            }

                            @{ var threadSummary = _threadSummaries.FirstOrDefault(t => t.RootMessageId == message.Id); }
                            @if (threadSummary is not null)
                            {
                                <div class="thread-link" @onclick="() => OpenThreadAsync(message)">
                                    @threadSummary.ReplyCount replies
                                </div>
                            }
                        </div>

                        @if (_hoveredMessageId == message.Id)
                        {
                            <div class="message-actions">
                                <button class="action-btn" @onclick="() => OpenThreadAsync(message)" title="Reply in thread">💬 Reply</button>
                                <div class="emoji-picker-wrapper">
                                    <button class="action-btn" @onclick="() => ToggleEmojiPicker(message.Id)" title="Add reaction">😀 React</button>
                                    @if (_emojiPickerMessageId == message.Id)
                                    {
                                        <div class="emoji-picker">
                                            @foreach (var emoji in _commonEmojis)
                                            {
                                                <button class="emoji-option" @onclick="() => AddReactionAsync(message.Id, emoji)">@emoji</button>
                                            }
                                        </div>
                                    }
                                </div>
                            </div>
                        }
                    </div>
                }
            </div>

            <div class="message-input-area">
                <textarea @bind="_newMessageContent" @bind:event="oninput"
                          @onkeydown="OnMessageKeyDown"
                          placeholder="Type a message..." rows="2"></textarea>
                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(_newMessageContent)">Send</button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </main>

    @* Right Panel - Thread View *@
    @if (_threadOpen && _threadRootMessage is not null)
    {
        <aside class="thread-panel">
            <div class="thread-header">
                <h3>Thread</h3>
                <button class="close-thread-btn" @onclick="CloseThread">✕</button>
            </div>
            <div class="thread-root-message">
                <div class="message-author">@_threadRootMessage.Author</div>
                <div class="message-text">@_threadRootMessage.Content</div>
            </div>
            <div class="thread-replies">
                @foreach (var reply in _threadMessages)
                {
                    <div class="message-item thread-reply">
                        <div class="message-author">@reply.Author</div>
                        <div class="message-timestamp">@FormatRelativeTime(reply.SentAt)</div>
                        <div class="message-text">@reply.Content</div>
                    </div>
                }
            </div>
            <div class="thread-input-area">
                <textarea @bind="_threadReplyContent" @bind:event="oninput"
                          @onkeydown="OnThreadKeyDown"
                          placeholder="Reply in thread..." rows="2"></textarea>
                <button class="send-btn" @onclick="SendThreadReplyAsync" disabled="@string.IsNullOrWhiteSpace(_threadReplyContent)">Reply</button>
            </div>
        </aside>
    }
</div>

@code {
    private List<Channel> _channels = new();
    private List<Message> _messages = new();
    private List<ThreadSummary> _threadSummaries = new();
    private List<Message> _threadMessages = new();

    private Channel? _activeChannel;
    private int? _activeChannelId;
    private Message? _threadRootMessage;
    private bool _threadOpen;

    private string _newMessageContent = string.Empty;
    private string _threadReplyContent = string.Empty;

    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;
    private bool _loadingMore;
    private bool _allMessagesLoaded;
    private int _messageSkip;
    private const int PageSize = 30;

    private ElementReference _messageListRef;
    private CancellationTokenSource _cts = new();

    private static readonly string[] _commonEmojis = { "👍", "❤️", "😂", "🎉", "🚀", "👀" };

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task SelectChannelAsync(Channel channel)
    {
        _activeChannel = channel;
        _activeChannelId = channel.Id;
        _messages.Clear();
        _threadSummaries.Clear();
        _messageSkip = 0;
        _allMessagesLoaded = false;

        await LoadMessagesAsync();
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channels to update unread counts
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMessagesAsync()
    {
        if (_activeChannelId is null || _allMessagesLoaded) return;

        _loadingMore = true;
        StateHasChanged();

        var newMessages = await ChatService.GetMessagesAsync(_activeChannelId.Value, _messageSkip, PageSize);

        if (newMessages.Count < PageSize)
        {
            _allMessagesLoaded = true;
        }

        // Prepend older messages
        _messages.InsertRange(0, newMessages);
        _messageSkip += newMessages.Count;

        // Build thread summaries from messages that have replies
        UpdateThreadSummaries();

        _loadingMore = false;
    }

    private void UpdateThreadSummaries()
    {
        var repliesByRoot = _messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();

        _threadSummaries = repliesByRoot;
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageContent) || _activeChannelId is null) return;

        var message = await ChatService.SendMessageAsync(_activeChannelId.Value, _newMessageContent.Trim(), null);
        _messages.Add(message);
        _newMessageContent = string.Empty;
        _messageSkip++;
    }

    private async Task OpenThreadAsync(Message rootMessage)
    {
        _threadRootMessage = rootMessage;
        _threadOpen = true;
        _threadReplyContent = string.Empty;
        _threadMessages = await ChatService.GetThreadAsync(rootMessage.Id);
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages.Clear();
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyContent) || _threadRootMessage is null || _activeChannelId is null) return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, _threadReplyContent.Trim(), _threadRootMessage.Id);
        _threadMessages.Add(reply);
        _messages.Add(reply);
        _threadReplyContent = string.Empty;
        UpdateThreadSummaries();
    }

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        _emojiPickerMessageId = null;

        // Refresh messages to show updated reactions
        if (_activeChannelId is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_activeChannelId.Value, 0, _messageSkip);
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task OnMessageListScroll()
    {
        // Triggered on scroll; load more when near top
        if (!_loadingMore && !_allMessagesLoaded)
        {
            await LoadMessagesAsync();
        }
    }

    private async Task OnMessageKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessageAsync();
        }
    }

    private async Task OnThreadKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendThreadReplyAsync();
        }
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;

        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hr ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays} days ago";
        return sentAt.ToString("MMM d, yyyy");
    }

    private static string TruncateDescription(string description)
    {
        return description.Length > 40 ? description[..37] + "..." : description;
    }

    public void Dispose()
    {
        _cts.Cancel();
        _cts.Dispose();
    }
}

.chat-container {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d21;
    color: #ccc;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #333;
}

.sidebar-header {
    padding: 16px;
    border-bottom: 1px solid #333;
}

.sidebar-header h3 {
    margin: 0;
    color: #fff;
    font-size: 1.1rem;
}

.channel-list {
    list-style: none;
    padding: 0;
    margin: 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 10px 16px;
    cursor: pointer;
    border-left: 3px solid transparent;
    position: relative;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #2c2f33;
}

.channel-item.active {
    background: #2c2f33;
    border-left-color: #4a9eff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    color: #fff;
}

.channel-description {
    font-size: 0.8rem;
    color: #999;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #e74c3c;
    color: #fff;
    font-size: 0.7rem;
    font-weight: bold;
    padding: 2px 7px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main Message Area */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #fff;
    min-width: 0;
}

.message-area.thread-open {
    max-width: 55%;
}

.message-header {
    padding: 16px 24px;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.message-header h2 {
    margin: 0;
    font-size: 1.2rem;
    color: #1a1d21;
}

.message-header p {
    margin: 4px 0 0;
    font-size: 0.85rem;
    color: #666;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 24px;
