    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

.close-thread-btn {
    border: none;
    background: transparent;
    font-size: 1.2rem;
    cursor: pointer;
    color: #666;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-thread-btn:hover {
    background: #e0e0e0;
}

.thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    background: #f0f4f8;
    flex-shrink: 0;
}

.thread-root-message .message-author {
    margin-bottom: 4px;
}

.thread-root-message .message-text {
    font-size: 0.85rem;
    color: #555;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-reply {
    padding: 8px 0;
    border-bottom: 1px solid #eee;
}

.thread-reply:last-child {
    border-bottom: none;
}

.thread-input-area {
    padding: 12px 16px;
}

/* No Channel Selected */
.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 1.1rem;
}
"}

